/**
 * SLATE — what pursuing each interest is, and what it does (from the connected attributes of 2026-10-09), read by
 * `systems/engagement.ts`.
 *
 * Generated from `docs/research/attributes/research-interests.json`: for each of the 64, an activity a Yale student
 * can actually do in New Haven (`activitySource`), and what the activity is to an actor (`actorUse`, with its
 * source where one was found; seven have none, said so by `actorUseSource` left out). Confidence is the
 * researcher's: 12 high, 24 medium, 28 low. No measured study links an actor's interests to better performance
 * (`research-acting-engine.json`, topic 9): the link is the conservatories' teaching, so what an interest develops
 * is small and ordinary (`ENGAGEMENT.weight`), never past the reach classes level off at.
 *
 * Each interest was given its own effect from its entry, not one bonus for all:
 * - `develops`: the ability or technique its actor's use names, grown a little by each session;
 * - `recovery`: the kind of rest it is, where research measures one (`RECOVERY`): a walk in nature, music, an hour
 *   with art, exercise, hands-on making, expressive writing, or switching off with a story. The trades studied as
 *   work (casting, lighting, editing and the rest) aren't rest, and give none.
 */

import type { AbilityId } from './abilities';
import type { Skill } from './school';

export type Recovery = 'nature' | 'music' | 'art' | 'exercise' | 'mastery' | 'writing' | 'detachment';

export interface InterestDef {
  develops: AbilityId | Skill;
  recovery?: Recovery;
  /** On your feet: refused too tired or hurt. */
  feet?: boolean;
  definition: string;
  activity: string;
  /** Where the activity is to be had; none for the twelve done at home, which no source names. */
  activitySource?: string;
  actorUse: string;
  actorUseSource?: string;
  confidence: 'high' | 'medium' | 'low';
  /** The researcher's caveat, where there is one. */
  notes?: string;
}

