/**
 * What each kind of rest does in an hour, before satiation, from topic 8 of the research: the stress it eases
 * (points) and the morale it lifts. Switching off and relaxation track lower fatigue most (Bennett, Bakker & Field
 * 2018: −.39 and −.35, correlations), mastery least (−.18); nature lowered cortisol 21.3% an hour past its daily fall
 * (Hunter et al. 2019) and a 90-minute walk lowered rumination (Bratman et al. 2015); music reduced stress at d = .38
 * to .55 (de Witte et al. 2020); a brief gallery visit lowered cortisol (Clow & Fredhoi 2006); expressive writing has a
 * small positive effect (Frattaroli 2006). The points are SLATE's scale for those orders.
 */
export const RECOVERY: Readonly<Record<Recovery, { stress: number; morale: number; source: string }>> = {
  nature: { stress: 8, morale: 2, source: 'Hunter et al. (2019); Bratman et al. (2015)' },
  music: { stress: 6, morale: 2, source: 'de Witte et al. (2020)' },
  art: { stress: 5, morale: 2, source: 'Clow & Fredhoi (2006)' },
  exercise: { stress: 6, morale: 1, source: 'Exercise and anxiety reviews (research-interests: fitness)' },
  mastery: { stress: 2, morale: 4, source: 'Bennett, Bakker & Field (2018), mastery' },
  writing: { stress: 4, morale: 1, source: 'Frattaroli (2006)' },
  detachment: { stress: 5, morale: 2, source: 'Bennett, Bakker & Field (2018), detachment' },
};

/**
 * Engagement's estimates (SLATE's, on the research's shape):
 * - a session is an hour (`minutes`), and grows its target as a quarter of a class (`weight`);
 * - familiarity rises a share of what's left each session (`familiarity`), through the four phases of interest
 *   Hidi & Renninger (2006) describe (`PHASES`);
 * - satiation rises with each session and halves every two days without one (`satiation`): enjoyment of a song played
 *   again at once fell by the sixth time, and a gap restored it (Galak, Kruger & Loewenstein 2011);
 * - an interest loved (on the character sheet) is a quarter better an hour of rest (`loved`), and learns nothing more:
 *   preference isn't expertise;
 * - genre familiarity and practice speed the preparation of work in the genre by at most a sixth (`genreSpeed`), the
 *   best of a work's genres and never their sum, and never cap what the work can reach.
 */
export const ENGAGEMENT = {
  minutes: 60,
  weight: 0.25,
  familiarity: 0.06,
  satiation: { perSession: 0.25, halfLifeDays: 2 },
  loved: 1.25,
  energy: { desk: 2, feet: 6 },
  met: { desk: 1.5, feet: 4 },
  genre: { study: 0.08, practice: 0.1, minutes: 90 },
  genreSpeed: 1 / 6,
} as const;

/** Hidi & Renninger's (2006) four phases of interest, by familiarity. */
export const PHASES: readonly { from: number; label: string }[] = [
  { from: 0, label: 'Triggered' },
  { from: 25, label: 'Maintained' },
  { from: 50, label: 'Emerging' },
  { from: 75, label: 'Well Developed' },
];
export const phaseOf = (familiarity: number): string => [...PHASES].reverse().find((p) => familiarity >= p.from)!.label;
